<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $order->reference }} Order Parchi</title><link rel="stylesheet" href="/print.css"></head><body><div class="print-actions"><button onclick="window.print()">Print / Save PDF</button><button onclick="window.close()">Close</button></div><main class="paper parchi-paper"><h1>ORDER PARCHI</h1><section class="parchi-meta"><div><small>Firm Name</small><strong>{{ $order->party_name }}</strong></div><div><small>Goods No.</small><strong>{{ $order->goods_number ?: $order->reference }}</strong><small>Date</small><strong>{{ date('d-m-Y', strtotime($order->date)) }}</strong></div></section><table class="print-table parchi-table"><thead><tr><th>Sr.</th><th>Description</th><th>KG</th><th>Qty. (Ton)</th><th>Pcs</th><th>Bundle</th></tr></thead><tbody>@foreach($items as $item)<tr><td>{{ $loop->iteration }}</td><td>{{ $item->description }}</td><td class="num">{{ number_format($item->weight_kg, 3) }}</td><td class="num">{{ number_format($item->quantity, 3) }}</td><td class="num">{{ $item->pieces ?: '' }}</td><td class="num">{{ $item->bundles ?: '' }}</td></tr>@endforeach @for($i=$items->count();$i<12;$i++)<tr class="blank"><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td></tr>@endfor</tbody><tfoot><tr><th colspan="3">TOTAL</th><th class="num">{{ number_format($items->sum('quantity'), 3) }}</th><th class="num">{{ number_format($items->sum('pieces')) }}</th><th class="num">{{ number_format($items->sum('bundles')) }}</th></tr></tfoot></table><section class="parchi-notes"><p><b>Pcs calculation:</b> Qty ÷ KG</p><p><b>Bundle calculation:</b> Qty ÷ 50</p></section><footer class="signature"><span>Prepared By</span><span>Store / Dispatch</span><span>Authorised Signatory</span></footer></main></body></html>
